const i="/api";async function s(t,n={}){const r=t.startsWith("http")?t:`${i}${t}`,u={headers:{"Content-Type":"application/json",...n.headers},credentials:"include"};try{const e=await fetch(r,{...u,...n});if(!e.ok){const c=await e.json().catch(()=>({})),o=new Error(c.message||`HTTP ${e.status}: ${e.statusText}`);throw o.status=e.status,o.data=c,o}return e.status===204||e.headers.get("content-length")==="0"?null:await e.json()}catch(e){throw console.error("[HTTP] 请求失败:",e),e}}function d(t,n={}){return s(t,{...n,method:"GET"})}function p(t,n,r={}){return s(t,{...r,method:"POST",body:JSON.stringify(n)})}function f(t,n,r={}){return s(t,{...r,method:"PUT",body:JSON.stringify(n)})}const a="/report-designer";async function h(t){return d(`${a}/${encodeURIComponent(t)}`)}async function T(t){return p(a,t)}async function l(t,n){return f(`${a}/${encodeURIComponent(t)}`,n)}export{T as c,h as g,l as u};
